// Enterprise Single Active Session Security Service
// Prevents account sharing between assessors; enforces 1 active session per account.

import { sendAccountInUseAlert, sendSelfForceLogoutAlert, sendAdminForceLogoutAlert } from './emailAlertService';
import { auth, signOut } from './firebase';

const STORE_KEY = 'hitecmedia_mock_db';
const SESSIONS_TABLE_KEY = 'hitec_user_sessions_v1';
const FIRESTORE_API_KEY = import.meta.env.VITE_FIREBASE_API_KEY || '';
const PROJECT_ID = import.meta.env.VITE_FIREBASE_PROJECT_ID || 'hitecapp-safety';
const IS_MOCK_MODE = !FIRESTORE_API_KEY || FIRESTORE_API_KEY === 'mock-api-key-hitecmedia';
const FIRESTORE_SESSIONS_BASE = `https://firestore.googleapis.com/v1/projects/${PROJECT_ID}/databases/(default)/documents/sessions`;

function sessionDocUrl(token, extraParams = '', useKey = true) {
  const key = (useKey && FIRESTORE_API_KEY) ? `?key=${FIRESTORE_API_KEY}` : '';
  const sep = key ? '&' : '?';
  return `${FIRESTORE_SESSIONS_BASE}/${token}${key}${extraParams ? sep + extraParams : ''}`;
}

async function firestorePatch(url, fields) {
  if (IS_MOCK_MODE) return;
  try {
    const headers = { 'Content-Type': 'application/json' };
    if (auth.currentUser) {
      const token = await auth.currentUser.getIdToken().catch(() => null);
      if (token) {
        headers['Authorization'] = `Bearer ${token}`;
        url = url.replace(/\?key=[^&]*/, '').replace(/&key=[^&]*/, '');
      }
    }
    fetch(url, {
      method: 'PATCH',
      headers,
      body: JSON.stringify({ fields })
    }).then(async res => {
      if (!res.ok) {
        const text = await res.text().catch(() => '');
        console.error('Firestore session write failed:', res.status, text);
      }
    }).catch(e => console.error('Firestore network error:', e));
  } catch (e) {}
}

async function firestorePost(token, fields) {
  if (IS_MOCK_MODE) return;
  try {
    let url = `${FIRESTORE_SESSIONS_BASE}?documentId=${token}`;
    if (FIRESTORE_API_KEY) {
      url += `&key=${FIRESTORE_API_KEY}`;
    }
    const headers = { 'Content-Type': 'application/json' };
    if (auth.currentUser) {
      const idToken = await auth.currentUser.getIdToken().catch(() => null);
      if (idToken) {
        headers['Authorization'] = `Bearer ${idToken}`;
        url = url.replace(/&key=[^&]*/, '').replace(/\?key=[^&]*/, '');
      }
    }
    fetch(url, {
      method: 'POST',
      headers,
      body: JSON.stringify({ fields })
    }).then(async res => {
      if (!res.ok) {
        const text = await res.text().catch(() => '');
        console.error('Firestore session create (POST) failed:', res.status, text);
        if (res.status === 409 || text.includes('ALREADY_EXISTS')) {
          firestorePatch(sessionDocUrl(token, '', false), fields);
        }
      }
    }).catch(e => console.error('Firestore network error:', e));
  } catch (e) {}
}

// Configuration flag for demo/mock environments
export const suppressCloudSyncWarning = true;

/**
 * Universal guard to prevent offline/sync warnings for local demo & admin accounts.
 */
export function shouldShowCloudSyncWarning(email, hasSyncError) {
  if (!hasSyncError) return false;
  if (suppressCloudSyncWarning) return false;
  
  // Explicitly suppress for standalone local accounts
  const lowerEmail = (email || '').toLowerCase();
  if (lowerEmail.includes('demo@hitec.id') || lowerEmail.includes('admin@hitec.id')) {
    return false;
  }
  
  return true;
}

/**
 * Production-safe diagnostic utility for mobile field auditing.
 * Invoke via Console: window.__hitecDebugAudit()
 */
export function registerDebugAudit() {
  if (typeof window === 'undefined') return;
  
  window.__hitecDebugAudit = function() {
    const rawDB = localStorage.getItem('hitecmedia_mock_db');
    let dbStatus = 'MISSING';
    let whitelistValid = false;

    try {
      if (rawDB) {
        const parsed = JSON.parse(rawDB);
        dbStatus = 'OK';
        whitelistValid = typeof parsed?.whitelist_users === 'object' && !Array.isArray(parsed?.whitelist_users);
      }
    } catch (e) {
      dbStatus = 'CORRUPTED_JSON';
    }

    const report = {
      timestamp: new Date().toISOString(),
      storageSchema: {
        status: dbStatus,
        whitelistIsArray: whitelistValid
      },
      demoMode: {
        suppressionFlagActive: true,
        domAttributePresent: document.documentElement.getAttribute('data-demo-mode') === 'true'
      },
      serviceWorker: {
        controller: !!navigator.serviceWorker?.controller,
        killSwitchActive: true
      }
    };

    console.table(report);
    return report;
  };
}

// Helper to get or generate unique device ID for this client
export const getClientDeviceId = () => {
  let deviceId = localStorage.getItem('hitec_session_device_id');
  if (!deviceId) {
    deviceId = 'dev_' + Math.random().toString(36).substring(2, 11) + '_' + Date.now().toString(36);
    localStorage.setItem('hitec_session_device_id', deviceId);
  }
  return deviceId;
};

// Helper to detect human-readable Device Name with phone model extraction
export const getClientDeviceName = () => {
  const ua = navigator.userAgent || '';

  let device = '';
  // Extract specific phone/tablet models
  if (ua.includes('iPhone')) {
    device = 'iPhone';
  } else if (ua.includes('iPad')) {
    device = 'iPad';
  } else if (ua.includes('SM-') || ua.includes('Samsung') || ua.includes('SAMSUNG')) {
    const m = ua.match(/SM-[A-Z0-9]+/i);
    device = m ? `Samsung ${m[0]}` : 'Samsung Galaxy';
  } else if (ua.includes('Xiaomi') || ua.includes('Redmi') || ua.includes('POCO')) {
    const m = ua.match(/(Redmi[^;)]*|POCO[^;)]*|Xiaomi[^;)]*)/i);
    device = m ? m[1].trim() : 'Xiaomi';
  } else if (ua.includes('HUAWEI') || ua.includes('Huawei')) {
    const m = ua.match(/HUAWEI[^;)]*/i);
    device = m ? m[0].trim() : 'Huawei';
  } else if (ua.includes('OPPO') || ua.includes('CPH')) {
    device = 'OPPO';
  } else if (ua.includes('vivo')) {
    device = 'Vivo';
  } else if (ua.includes('Pixel')) {
    const m = ua.match(/Pixel[^;)]*/i);
    device = m ? `Google ${m[0].trim()}` : 'Google Pixel';
  } else if (ua.includes('Android')) {
    const m = ua.match(/;\s*([^;)]+)\s*Build/i);
    device = m ? m[1].trim() : 'Android Device';
  } else if (ua.includes('Win')) {
    device = 'Windows PC';
  } else if (ua.includes('Mac')) {
    device = 'macOS';
  } else if (ua.includes('Linux')) {
    device = 'Linux PC';
  } else {
    device = 'Unknown Device';
  }

  let browser = '';
  if (ua.includes('Edg')) browser = 'Edge';
  else if (ua.includes('OPR') || ua.includes('Opera')) browser = 'Opera';
  else if (ua.includes('Chrome') && !ua.includes('Edg')) browser = 'Chrome';
  else if (ua.includes('Safari') && !ua.includes('Chrome')) browser = 'Safari';
  else if (ua.includes('Firefox')) browser = 'Firefox';
  else browser = 'Browser';

  return `${device} - ${browser}`;
};

// Helper to load sessions DB table
const loadSessionsTable = () => {
  try {
    const raw = localStorage.getItem(SESSIONS_TABLE_KEY);
    return raw ? JSON.parse(raw) : [];
  } catch {
    return [];
  }
};

const saveSessionsTable = (sessions) => {
  localStorage.setItem(SESSIONS_TABLE_KEY, JSON.stringify(sessions));
};

export const getSanitizedMockDB = () => {
  const defaultStore = { whitelist_users: {} };
  try {
    const raw = localStorage.getItem(STORE_KEY);
    if (!raw || raw === 'undefined' || raw === 'null') {
      return defaultStore;
    }
    const parsed = JSON.parse(raw);
    if (typeof parsed !== 'object' || parsed === null) {
      return defaultStore;
    }

    if (!parsed.whitelist_users || typeof parsed.whitelist_users !== 'object' || Array.isArray(parsed.whitelist_users)) {
      parsed.whitelist_users = {};
    }
    return parsed;
  } catch (e) {
    console.error("sessionSecurity: Fatal parse error, falling back to default.", e);
    return defaultStore;
  }
};

